using Finora.Application;namespace Finora.Infrastructure;public sealed class PrivacyLogger(string directory):IPrivacyLogger{private readonly string _path=Path.Combine(directory,"finora-diagnostic.log");private readonly SemaphoreSlim _gate=new(1,1);public void Information(string eventName,IReadOnlyDictionary<string,object?>? properties=null)=>_=Write("INFO",eventName);public void Error(Exception exception,string eventName)=>_=Write("ERROR",$"{eventName}|{exception.GetType().Name}");public async Task<string>ExportSanitizedLogAsync(CancellationToken c=default){await _gate.WaitAsync(c);try{Directory.CreateDirectory(Path.GetDirectoryName(_path)!);if(!File.Exists(_path))await File.WriteAllTextAsync(_path,string.Empty,c);return _path;}finally{_gate.Release();}}private async Task Write(string level,string name){try{Directory.CreateDirectory(Path.GetDirectoryName(_path)!);await _gate.WaitAsync();try{var safe=new string(name.Where(ch=>char.IsLetterOrDigit(ch)||ch is '.' or '_' or '-').Take(100).ToArray());await File.AppendAllTextAsync(_path,$"{DateTimeOffset.UtcNow:O}|{level}|{safe}\n");}finally{_gate.Release();}}catch{}}}
